class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        from itertools import combinations
        S = set(map(tuple, points))
        ans = -1
        for quad in combinations(points, 4):
            xs = sorted(p[0] for p in quad)
            ys = sorted(p[1] for p in quad)
            if xs[0] == xs[1] < xs[2] == xs[3] and ys[0] == ys[1] < ys[2] == ys[3]:
                x1, x2, y1, y2 = xs[0], xs[3], ys[0], ys[3]
                corners = {(x1,y1),(x1,y2),(x2,y1),(x2,y2)}
                if not any(x1 <= p[0] <= x2 and y1 <= p[1] <= y2
                           for p in points if tuple(p) not in corners):
                    ans = max(ans, (x2-x1)*(y2-y1))
        return ans

