class Solution {
    public int maxRectangleArea(int[][] points) {
        int n = points.length, ans = -1;
        Set<Long> S = new HashSet<>();
        for (int[] p : points) S.add(p[0] * 1000L + p[1]);
        for (int a = 0; a < n; a++)
        for (int b = a+1; b < n; b++)
        for (int c = b+1; c < n; c++)
        for (int d = c+1; d < n; d++) {
            int[][] q = {points[a], points[b], points[c], points[d]};
            int[] xs = new int[4], ys = new int[4];
            for (int i = 0; i < 4; i++) { xs[i] = q[i][0]; ys[i] = q[i][1]; }
            Arrays.sort(xs); Arrays.sort(ys);
            if (xs[0]==xs[1] && xs[2]==xs[3] && xs[1]<xs[2] &&
                ys[0]==ys[1] && ys[2]==ys[3] && ys[1]<ys[2]) {
                int x1=xs[0], x2=xs[3], y1=ys[0], y2=ys[3];
                boolean ok = true;
                for (int[] p : points) {
                    long key = p[0]*1000L + p[1];
                    if (key==x1*1000L+y1 || key==x1*1000L+y2 || key==x2*1000L+y1 || key==x2*1000L+y2) continue;
